8	export function ProjectsStatsBar({ stats }: ProjectsStatsBarProps) {
9	  const { activeCount, depositPoolCents, avgCompletionPct } = stats
10	
11	  if (activeCount === 0 && depositPoolCents === 0) return null
12	
13	  return (
14	    <p className="text-xs text-muted-foreground tabular-nums" data-testid="projects-stats-bar">
15	      <span className="text-foreground font-medium">{activeCount}</span>{' '}
16	      {activeCount === 1 ? 'active' : 'active'}
17	      {depositPoolCents > 0 && (
18	        <>
19	          {' · '}
20	          <span className="text-foreground font-medium">
21	            {formatCurrency(depositPoolCents)}
22	          </span>{' '}
23	          in deposit pools
24	        </>
25	      )}
26	      {avgCompletionPct > 0 && (
27	        <>
28	          {' · '}
29	          <span className="text-foreground font-medium">{avgCompletionPct}%</span>{' '}
30	          avg completion
31	        </>
32	      )}
33	    </p>
34	  )
35	}
