60	type MutationRole = 'owner' | 'admin' | 'artist'
61	type ReadRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'
62	
63	function canWrite(role: ReadRole): role is MutationRole {
64	  return role === 'owner' || role === 'admin' || role === 'artist'
65	}
66	
67	function canAdmin(role: ReadRole): boolean {
68	  return role === 'owner' || role === 'admin'
69	}
