/**
 * Aggregate quick stats for the projects list header bar.
 * Returns active count, total deposit pool balance, and average completion %.
 */
export async function getProjectsStats(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string
): Promise<ProjectsStats> {
  const { data, error } = await supabase
    .from('projects')
    .select('status, deposit_pool_cents, deposit_applied_cents, sessions_completed, total_sessions_planned')
    .eq('studio_id', studioId)
    .not('status', 'in', '(cancelled)')

  if (error) {
    logger.error({ error, studioId }, 'getProjectsStats failed — returning zeros')
    return { activeCount: 0, depositPoolCents: 0, avgCompletionPct: 0 }
  }

  const rows = data ?? []

  let activeCount = 0
  let depositPoolCents = 0
  let completionSum = 0
  let completionCount = 0

  for (const row of rows) {
    if (row.status === 'active' || row.status === 'deposit_paid' || row.status === 'healing') {
      activeCount++
    }

    const balance = row.deposit_pool_cents - row.deposit_applied_cents
    if (balance > 0) {
      depositPoolCents += balance
    }

    if (row.total_sessions_planned && row.total_sessions_planned > 0) {
      completionSum += (row.sessions_completed * 100) / row.total_sessions_planned
      completionCount++
    }
  }

  const avgCompletionPct = completionCount > 0
    ? Math.round(completionSum / completionCount)
    : 0

  return { activeCount, depositPoolCents, avgCompletionPct }
}

