import { formatCurrency } from '@/lib/utils'
import type { ProjectsStats } from '@/lib/projects/queries'

interface ProjectsQuickStatsProps {
  stats: ProjectsStats
}

interface StatCardProps {
  label: string
  value: string
  sub: string
}

function StatCard({ label, value, sub }: StatCardProps) {
  return (
    <div className="rounded-lg border border-border bg-card px-5 py-4 shadow-[var(--shadow-card)]">
      <p
        className="text-[10px] font-bold uppercase tracking-[0.12em] text-muted-foreground mb-1"
        style={{ letterSpacing: '0.12em' }}
      >
        {label}
      </p>
      <p className="text-2xl font-bold tabular-nums text-foreground leading-none mb-1">
        {value}
      </p>
      <p className="text-xs text-muted-foreground">{sub}</p>
    </div>
  )
}

export function ProjectsQuickStats({ stats }: ProjectsQuickStatsProps) {
  const { activeCount, depositPoolCents, avgCompletionPct } = stats

  return (
    <div
      className="grid grid-cols-1 sm:grid-cols-3 gap-3"
      data-testid="projects-quick-stats"
    >
      <StatCard
        label="Active"
        value={String(activeCount)}
        sub="deposit paid · active · healing"
      />
      <StatCard
        label="In Deposit Pools"
        value={depositPoolCents > 0 ? formatCurrency(depositPoolCents) : '$0'}
        sub="unspent pool balances"
      />
      <StatCard
        label="Avg Completion"
        value={avgCompletionPct > 0 ? `${avgCompletionPct}%` : '—'}
        sub="sessions completed / planned"
      />
    </div>
  )
}

'use client'

import Link from 'next/link'
import { FolderKanban } from 'lucide-react'
import { cn, formatCurrency } from '@/lib/utils'
import type { ProjectListItem } from '@/lib/projects/queries'

// ─── Helpers ──────────────────────────────────────────────────────────────────

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase() ?? '')
    .join('')
}

function stalledDays(stalledAt: string): number {
  return Math.floor((Date.now() - new Date(stalledAt).getTime()) / (24 * 60 * 60 * 1000))
}

// ─── Deposit pill ─────────────────────────────────────────────────────────────

function DepositPill({ project }: { project: ProjectListItem }) {
  const { deposit_pool_cents, deposit_applied_cents, status, stalled_at, sessions_completed, total_sessions_planned } = project

  // Stalled overrides everything
  if (stalled_at) {
    const days = stalledDays(stalled_at)
    return (
      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-medium bg-warning-bg text-warning-foreground">
        Stalled {days}d
      </span>
    )
  }

  // Paid in full — last sessions done and project closing
  if (
    total_sessions_planned &&
    sessions_completed >= total_sessions_planned &&
    (status === 'healing' || status === 'completed')
  ) {
    return (
      <span className="px-2 py-0.5 rounded text-[10px] font-medium bg-success-bg text-success-foreground">
        Paid in full
      </span>
    )
  }

  // Pool fully applied
  if (deposit_pool_cents > 0 && deposit_applied_cents >= deposit_pool_cents) {
    return (
      <span className="px-2 py-0.5 rounded text-[10px] font-medium bg-secondary text-secondary-foreground" style={{ color: 'oklch(40% 0.12 270)' }}>
        Pool applied
      </span>
    )
  }

  // Positive pool balance remaining
  const balance = deposit_pool_cents - deposit_applied_cents
  if (balance > 0) {
    return (
      <span className="px-2 py-0.5 rounded text-[10px] font-medium bg-success-bg text-success-foreground">
        {formatCurrency(balance)} in pool
      </span>
    )
  }

  // Deposit pending (no pool, still planning)
  if (deposit_pool_cents === 0 && status === 'planning') {
    return (
      <span className="px-2 py-0.5 rounded text-[10px] font-medium bg-warning-bg text-warning-foreground">
        Deposit pending
      </span>
    )
  }

  return null
}

// ─── Moodboard tile grid ──────────────────────────────────────────────────────

// Placeholder gradient tiles using brand colors when fewer than 4 images
const PLACEHOLDER_TILE_CLASSES = [
  'bg-[var(--color-rust)]/10',
  'bg-[var(--color-onyx)]/8',
  'bg-[var(--color-stone)]/15',
  'bg-[var(--color-rust)]/6',
] as const

interface MoodboardGridProps {
  thumbnails: (string | null)[]
  projectName: string
}

function MoodboardGrid({ thumbnails, projectName }: MoodboardGridProps) {
  const tiles = Array.from({ length: 4 }, (_, i) => thumbnails[i] ?? null)

  // If at least one real image, build a 2×2 grid
  const hasAny = tiles.some(Boolean)

  if (!hasAny) {
    return (
      <div className="aspect-video rounded-md overflow-hidden bg-muted flex items-center justify-center border-b border-border/60">
        <FolderKanban className="h-8 w-8 text-muted-foreground/30" aria-hidden="true" />
      </div>
    )
  }

  return (
    <div className="aspect-video grid grid-cols-2 grid-rows-2 gap-[2px] rounded-md overflow-hidden border-b border-border/60 bg-muted">
      {tiles.map((src, idx) =>
        src ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            key={idx}
            src={src}
            alt={idx === 0 ? projectName : ''}
            className="h-full w-full object-cover"
          />
        ) : (
          <div key={idx} className={cn('h-full w-full', PLACEHOLDER_TILE_CLASSES[idx])} />
        )
      )}
    </div>
  )
}

// ─── Style tag chips ──────────────────────────────────────────────────────────

function StyleTags({ tags }: { tags: string[] }) {
  if (tags.length === 0) return null
  const visible = tags.slice(0, 2)
  const overflow = tags.length - 2

  return (
    <div className="flex flex-wrap gap-1">
      {visible.map((tag) => (
        <span
          key={tag}
          className="px-1.5 py-0.5 rounded text-[10px] font-medium bg-secondary text-secondary-foreground"
        >
          {tag}
        </span>
      ))}
      {overflow > 0 && (
        <span className="px-1.5 py-0.5 rounded text-[10px] font-medium bg-secondary text-muted-foreground">
          +{overflow}
        </span>
      )}
    </div>
  )
}

// ─── Progress bar ─────────────────────────────────────────────────────────────

function SessionProgressBar({
  completed,
  planned,
}: {
  completed: number
  planned: number | null
}) {
  if (!planned || planned === 0) return null
  const pct = Math.min(100, Math.round((completed / planned) * 100))

  return (
    <div className="space-y-1">
      <div className="h-[2px] rounded-full bg-muted overflow-hidden">
        <div
          className="h-full rounded-full bg-[var(--color-rust)] transition-all duration-300"
          style={{ width: `${pct}%` }}
          role="progressbar"
          aria-valuenow={pct}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-label={`${completed} of ${planned} sessions complete`}
        />
      </div>
      <p className="text-[10px] tabular-nums text-muted-foreground">
        {completed}/{planned} sessions
      </p>
    </div>
  )
}

// ─── Artist avatar ────────────────────────────────────────────────────────────

function ArtistAvatar({
  artist,
}: {
  artist: { display_name: string; avatar_url: string | null } | null
}) {
  if (!artist) return null

  if (artist.avatar_url) {
    return (
      // eslint-disable-next-line @next/next/no-img-element
      <img
        src={artist.avatar_url}
        alt={artist.display_name}
        title={artist.display_name}
        className="h-8 w-8 rounded-full object-cover border-2 border-card"
      />
    )
  }

  return (
    <div
      className="h-8 w-8 rounded-full bg-accent flex items-center justify-center text-[9px] font-bold text-accent-foreground border-2 border-card"
      title={artist.display_name}
      aria-label={artist.display_name}
    >
      {getInitials(artist.display_name)}
    </div>
  )
}

// ─── Card ─────────────────────────────────────────────────────────────────────

interface ProjectCardProps {
  project: ProjectListItem
  /**
   * Optional array of thumbnail URLs from project_references (first 4).
   * When not provided, falls back to cover_photo_url or placeholders.
   */
  thumbnails?: string[]
}

export function ProjectCard({ project, thumbnails }: ProjectCardProps) {
  const clientName = project.client
    ? `${project.client.first_name}${project.client.last_name ? ` ${project.client.last_name}` : ''}`
    : 'Unknown client'

  // Build 4-tile moodboard from thumbnails or fall back to cover_photo_url
  const moodTiles: (string | null)[] = thumbnails
    ? thumbnails.slice(0, 4)
    : project.cover_photo_url
    ? [project.cover_photo_url, null, null, null]
    : []

  return (
    <Link
      href={`/projects/${project.id}`}
      data-testid={`project-card-${project.id}`}
      className={cn(
        'group relative block rounded-xl border border-border bg-card overflow-hidden',
        'transition-all duration-200 ease-out',
        'shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-card-hover)]',
        'hover:-translate-y-0.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring'
      )}
    >
