// ─── Constants ────────────────────────────────────────────────────────────────

type BoardStatus = 'planning' | 'deposit_paid' | 'active' | 'healing' | 'completed'

const BOARD_COLUMNS: { id: BoardStatus; label: string }[] = [
  { id: 'planning', label: 'Planning' },
  { id: 'deposit_paid', label: 'Deposit Paid' },
  { id: 'active', label: 'Active' },
  { id: 'healing', label: 'Healing' },
  { id: 'completed', label: 'Complete' },
]

const BOARD_STATUS_SET = new Set<string>(BOARD_COLUMNS.map((c) => c.id))

// ─── Transition copy ──────────────────────────────────────────────────────────

function transitionMessage(from: BoardStatus, to: BoardStatus): string {
  const ordered = BOARD_COLUMNS.map((c) => c.id)
  const fromIdx = ordered.indexOf(from)
  const toIdx = ordered.indexOf(to)
  const isReverse = toIdx < fromIdx

  if (isReverse) {
    return `Move back to "${BOARD_COLUMNS[toIdx]?.label ?? to}"? This reverses the project status.`
  }

  if (from === 'planning' && to === 'deposit_paid') {
    return 'Request deposit from client? For now this just confirms the status change. Dodo payment link wiring lands in Sprint 5.'
  }
  if (from === 'deposit_paid' && to === 'active') {
    return 'Mark first session scheduled and project active?'
  }
  if (from === 'active' && to === 'healing') {
    return 'Mark all sessions complete? The project will enter the healing phase.'
  }
  if (from === 'healing' && to === 'completed') {
    return 'Mark this project fully complete? This closes the deposit pool and archives the timeline.'
  }

  return `Move project from ${from.replace('_', ' ')} to ${to.replace('_', ' ')}?`
}

// ─── Transition dialog ────────────────────────────────────────────────────────

interface PendingTransition {
  projectId: string
  projectName: string
  fromStatus: BoardStatus
  toStatus: BoardStatus
}

interface TransitionDialogProps {
  open: boolean
  transition: PendingTransition
  onConfirm: () => void
  onCancel: () => void
  isPending: boolean
}

function TransitionDialog({
  open,
  transition,
  onConfirm,
  onCancel,
  isPending,
}: TransitionDialogProps) {
  const { projectName, fromStatus, toStatus } = transition
  const ordered = BOARD_COLUMNS.map((c) => c.id)
  const isReverse = ordered.indexOf(toStatus) < ordered.indexOf(fromStatus)

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onCancel()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="text-base font-semibold">Confirm status change</DialogTitle>
        </DialogHeader>
        <p className="text-sm text-muted-foreground">
          <span className="font-medium text-foreground">{projectName}</span>
          {' — '}
          {transitionMessage(fromStatus, toStatus)}
        </p>
        <DialogFooter className="gap-2">
          <Button variant="outline" size="sm" onClick={onCancel} disabled={isPending}>
            Cancel
          </Button>
          <Button
            size="sm"
            onClick={onConfirm}
            disabled={isPending}
            variant={isReverse ? 'destructive' : 'default'}
          >
            {isPending ? 'Saving…' : 'Confirm'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase() ?? '')
    .join('')
}

function stalledDays(stalledAt: string): number {
  return Math.floor((Date.now() - new Date(stalledAt).getTime()) / (24 * 60 * 60 * 1000))
}

// ─── Deposit pill (board-specific) ───────────────────────────────────────────

function DepositPill({ project }: { project: ProjectListItem }) {
  const {
    deposit_pool_cents,
    deposit_applied_cents,
    status,
    stalled_at,
    sessions_completed,
    total_sessions_planned,
  } = project

  if (stalled_at) {
    const days = stalledDays(stalled_at)
    return (
      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-medium bg-warning-bg text-warning-foreground">
        Stalled {days}d
      </span>
    )
  }

  if (
    total_sessions_planned &&
    sessions_completed >= total_sessions_planned &&
    (status === 'healing' || status === 'completed')
  ) {
    return (
      <span className="px-2 py-0.5 rounded text-[10px] font-medium bg-success-bg text-success-foreground">
        Paid in full
      </span>
    )
  }

  const balance = deposit_pool_cents - deposit_applied_cents

  if (deposit_pool_cents > 0 && deposit_applied_cents >= deposit_pool_cents) {
    return (
      <span className="px-2 py-0.5 rounded text-[10px] font-medium bg-secondary text-muted-foreground">
        Pool applied
      </span>
    )
  }

  if (balance > 0) {
    return (
      <span className="px-2 py-0.5 rounded text-[10px] font-medium bg-success-bg text-success-foreground">
        {formatCurrency(balance)} in pool
      </span>
    )
  }

  if (deposit_pool_cents === 0 && status === 'planning') {
    return (
      <span className="px-2 py-0.5 rounded text-[10px] font-medium bg-warning-bg text-warning-foreground">
        Deposit pending
      </span>
    )
  }

  return null
}

