          </span>
          <span className="text-[11px] font-medium tabular-nums text-muted-foreground/60">
            {projects.length}
          </span>
        </div>
        {canCreate && (
          <button
            onClick={() => router.push(`/projects/new?status=${status}`)}
            className="h-5 w-5 rounded flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
            aria-label={`New ${label} project`}
