  label: string
  active: boolean
  onToggle: () => void
}) {
  if (active) {
    return (
      <button
        onClick={onToggle}
        className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-medium bg-foreground text-background transition-colors"
        aria-pressed="true"
      >
        {label}
        <X className="h-2.5 w-2.5" aria-hidden="true" />
      </button>
    )
  }

  return (
    <button
      onClick={onToggle}
      className={cn(
        'px-2.5 py-1 rounded-full text-[11px] font-medium border border-border',
        'text-muted-foreground hover:text-foreground hover:border-foreground/30 transition-colors'
      )}
      aria-pressed="false"
    >
      {label}
    </button>
  )
}

// ─── Filters ──────────────────────────────────────────────────────────────────

export function ProjectFilters({
  activeStatuses,
  activeArtistId,
  artists,
  showArchived = false,
  onStatusToggle,
  onArtistToggle,
  onToggleShowArchived,
  onClear,
}: ProjectFiltersProps) {
  const hasActiveFilters = activeStatuses.length > 0 || activeArtistId !== null

  const handleStatusToggle = useCallback(
    (s: ProjectStatus) => {
      onStatusToggle(s)
    },
    [onStatusToggle]
  )

  const visibleStatuses = showArchived ? ALL_STATUSES : DEFAULT_STATUSES

  return (
    <div className="flex flex-wrap items-center gap-1.5">
      {/* Status chips */}
      {visibleStatuses.map((s) => (
        <FilterChip
          key={s}
          label={STATUS_LABELS[s]}
          active={activeStatuses.includes(s)}
          onToggle={() => handleStatusToggle(s)}
        />
      ))}

      {/* Show / hide archived toggle */}
      <button
        onClick={onToggleShowArchived}
        className="px-2.5 py-1 rounded-full text-[11px] font-medium border border-dashed border-border text-muted-foreground hover:text-foreground hover:border-foreground/30 transition-colors"
      >
        {showArchived ? 'Hide archived' : '+ Archived'}
      </button>

      {/* Artist chips (separator) */}
      {artists.length > 0 && (
        <>
          <span className="h-3 w-px bg-border" role="separator" aria-hidden="true" />
          {artists.map((a) => (
            <FilterChip
              key={a.id}
              label={a.display_name}
              active={activeArtistId === a.id}
              onToggle={() => onArtistToggle(a.id)}
            />
          ))}
        </>
      )}

      {/* Clear all */}
      {hasActiveFilters && (
        <button
          onClick={onClear}
          className="px-2.5 py-1 text-[11px] text-muted-foreground hover:text-foreground transition-colors"
        >
          Clear all
        </button>
      )}
    </div>
  )
}

import { formatCurrency } from '@/lib/utils'
