// ─── Types ────────────────────────────────────────────────────────────────────

type ViewMode = 'board' | 'list' | 'gallery' | 'timeline'

const SORT_OPTIONS = [
  { value: 'updated_at', label: 'Last activity' },
  { value: 'created_at', label: 'Created date' },
  { value: 'client_name', label: 'Client name' },
  { value: 'deposit_balance', label: 'Deposit balance' },
  { value: 'sessions', label: 'Session count' },
  { value: 'artist', label: 'Artist' },
] as const

type SortOption = (typeof SORT_OPTIONS)[number]['value']

const STATUS_LABELS: Record<string, string> = {
  planning: 'Planning',
  deposit_paid: 'Deposit Paid',
  active: 'Active',
  healing: 'Healing',
  completed: 'Completed',
  on_hold: 'On Hold',
  cancelled: 'Archived',
}

const TABLE_STATUS_CONFIG: Record<string, string> = {
  planning: 'bg-secondary text-secondary-foreground',
  deposit_paid: 'bg-success-bg text-success-foreground',
  active: 'bg-success-bg text-success-foreground',
  healing: 'bg-warning-bg text-warning-foreground',
  completed: 'bg-secondary text-secondary-foreground',
  on_hold: 'bg-warning-bg text-warning-foreground',
  cancelled: 'bg-muted text-muted-foreground',
}

const VIEW_OPTIONS: { id: ViewMode; label: string; icon: React.ReactNode }[] = [
  { id: 'board', label: 'Board', icon: <Columns3 className="h-3.5 w-3.5" /> },
  { id: 'list', label: 'List', icon: <List className="h-3.5 w-3.5" /> },
  { id: 'gallery', label: 'Gallery', icon: <LayoutGrid className="h-3.5 w-3.5" /> },
  { id: 'timeline', label: 'Timeline', icon: <CalendarClock className="h-3.5 w-3.5" /> },
]

const LS_VIEW_KEY = 'inkos.projects.view'

// ─── URL param helpers ────────────────────────────────────────────────────────

function serializeStatuses(statuses: ProjectStatus[]): string {
  return statuses.join(',')
}

function parseStatuses(raw: string | null): ProjectStatus[] {
  if (!raw) return []
  const VALID: Set<string> = new Set([
    'planning', 'deposit_paid', 'active', 'healing', 'completed', 'on_hold', 'cancelled',
  ])
  return raw.split(',').filter((s) => VALID.has(s)) as ProjectStatus[]
}

// ─── View toggle ──────────────────────────────────────────────────────────────

interface ViewToggleProps {
  current: ViewMode
  onChange: (mode: ViewMode) => void
}

function ViewToggle({ current, onChange }: ViewToggleProps) {
  return (
    <div className="flex items-center gap-0.5 rounded-md border border-border p-0.5">
      {VIEW_OPTIONS.map(({ id, label, icon }) => (
        <button
          key={id}
