// ─── Main client ──────────────────────────────────────────────────────────────

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
  sort_order: number
}

interface ProjectsListClientProps {
  initialProjects: ProjectListItem[]
  stats: ProjectsStats
  artists: Artist[]
  role: string
  initialFilters: ListProjectsFilters
}

export function ProjectsListClient({
  initialProjects,
  stats,
  artists,
  role,
  initialFilters,
}: ProjectsListClientProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const [isPending, startTransition] = useTransition()

  // ── View mode (localStorage-persisted) ────────────────────────────────────
  const [viewMode, setViewMode] = useState<ViewMode>('board')

  useEffect(() => {
    try {
      const stored = localStorage.getItem(LS_VIEW_KEY)
      if (stored && ['board', 'list', 'gallery', 'timeline'].includes(stored)) {
        setViewMode(stored as ViewMode)
      }
    } catch {
      // localStorage may be unavailable in some environments
    }
  }, [])

  const handleViewChange = useCallback((mode: ViewMode) => {
    setViewMode(mode)
    try {
      localStorage.setItem(LS_VIEW_KEY, mode)
    } catch {
      // ignore
    }
  }, [])

  // ── Demo mode ─────────────────────────────────────────────────────────────
  const isDemo = searchParams.get('demo') === '1'
  const projects = isDemo ? getDemoProjects() : initialProjects

  const dismissDemo = useCallback(() => {
    router.push('/projects/new')
  }, [router])

  // ── Search (debounced → URL) ──────────────────────────────────────────────
  const [searchValue, setSearchValue] = useState(initialFilters.search ?? '')
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const updateParam = useCallback(
    (key: string, value: string | null) => {
      const current = new URLSearchParams(Array.from(searchParams.entries()))
      if (value) {
        current.set(key, value)
      } else {
        current.delete(key)
      }
      const qs = current.toString()
      startTransition(() => {
        router.push(`${pathname}${qs ? `?${qs}` : ''}`)
      })
    },
    [router, pathname, searchParams]
  )

  const handleSearchChange = useCallback(
    (value: string) => {
      setSearchValue(value)
      if (debounceRef.current) clearTimeout(debounceRef.current)
      debounceRef.current = setTimeout(() => {
        updateParam('search', value || null)
      }, 300)
    },
    [updateParam]
  )

  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current)
    }
  }, [])

  // ── Multi-status filter ───────────────────────────────────────────────────
  const activeStatuses = parseStatuses(searchParams.get('statuses'))

  const handleStatusToggle = useCallback(
    (status: ProjectStatus) => {
      const next = activeStatuses.includes(status)
        ? activeStatuses.filter((s) => s !== status)
        : [...activeStatuses, status]
      updateParam('statuses', next.length > 0 ? serializeStatuses(next) : null)
    },
    [activeStatuses, updateParam]
  )

  // ── Artist filter ─────────────────────────────────────────────────────────
  const activeArtistId = searchParams.get('artistId') ?? null

  const handleArtistToggle = useCallback(
    (artistId: string) => {
      updateParam('artistId', activeArtistId === artistId ? null : artistId)
    },
    [activeArtistId, updateParam]
  )

  // ── Show archived toggle ──────────────────────────────────────────────────
  const showArchived = searchParams.get('archived') === '1'

  const handleToggleShowArchived = useCallback(() => {
    updateParam('archived', showArchived ? null : '1')
  }, [showArchived, updateParam])

  const handleClearFilters = useCallback(() => {
    const current = new URLSearchParams(Array.from(searchParams.entries()))
    current.delete('statuses')
    current.delete('artistId')
    current.delete('archived')
    const qs = current.toString()
    startTransition(() => {
      router.push(`${pathname}${qs ? `?${qs}` : ''}`)
    })
  }, [router, pathname, searchParams])

  // ── Sort ──────────────────────────────────────────────────────────────────
  const activeSort = (searchParams.get('sort') as SortOption | null) ?? 'updated_at'

  const handleSortChange = useCallback(
    (value: string) => {
      updateParam('sort', value === 'updated_at' ? null : value)
    },
    [updateParam]
  )

  const canCreate = role !== 'guest_artist'

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <div className="space-y-4">
      {/* Demo banner */}
      {isDemo && <DemoBanner onDismiss={dismissDemo} />}

      {/* Quick stats KPI cards */}
      {!isDemo && <ProjectsQuickStats stats={stats} />}

      {/* Filter + sort + view row */}
      <div className="flex flex-wrap items-start gap-2">
        {/* Search */}
        <div className="relative flex-1 min-w-[180px] max-w-xs">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
          <Input
            placeholder="Search projects…"
            value={searchValue}
            onChange={(e) => handleSearchChange(e.target.value)}
            className="pl-8 h-9 text-sm"
          />
          {searchValue && (
            <button
              onClick={() => handleSearchChange('')}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              aria-label="Clear search"
            >
              <X className="h-3 w-3" />
            </button>
          )}
        </div>

        {/* Sort dropdown */}
        <Select value={activeSort} onValueChange={handleSortChange}>
          <SelectTrigger className="h-9 w-40 text-sm">
            <SelectValue placeholder="Sort by…" />
          </SelectTrigger>
          <SelectContent>
            {SORT_OPTIONS.map(({ value, label }) => (
              <SelectItem key={value} value={value}>
                {label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        {/* View toggle — right-aligned */}
        <div className="ml-auto">
          <ViewToggle current={viewMode} onChange={handleViewChange} />
        </div>
      </div>

      {/* Filter chips row */}
      <ProjectFilters
        activeStatuses={activeStatuses}
        activeArtistId={activeArtistId}
        artists={artists}
        showArchived={showArchived}
        onStatusToggle={handleStatusToggle}
        onArtistToggle={handleArtistToggle}
        onToggleShowArchived={handleToggleShowArchived}
        onClear={handleClearFilters}
      />

      {/* Content area */}
      <div className="flex-1">
        {isPending ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {Array.from({ length: 6 }).map((_, i) => (
              <Skeleton key={i} className="h-64 rounded-xl" />
            ))}
          </div>
        ) : projects.length === 0 ? (
          <EmptyProjects
            canCreate={canCreate}
            onNew={() => router.push('/projects/new')}
            onDemo={() => {
              const qs = new URLSearchParams(Array.from(searchParams.entries()))
              qs.set('demo', '1')
              router.push(`${pathname}?${qs.toString()}`)
            }}
          />
        ) : viewMode === 'board' ? (
          <ProjectsBoardView projects={projects} canCreate={canCreate} />
        ) : viewMode === 'gallery' ? (
          <ProjectsGalleryView projects={projects} />
        ) : viewMode === 'timeline' ? (
          <TimelineComingSoon />
        ) : (
          <ProjectsTable projects={projects} />
        )}
      </div>
    </div>
  )
}

