import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { Plus } from 'lucide-react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { listProjects, getProjectsStats } from '@/lib/projects/queries'
import { ProjectsListClient } from '@/components/projects/ProjectsListClient'
import { Page, type PageAction } from '@/components/shared/Page'
import { Skeleton } from '@/components/ui/skeleton'
import type { ListProjectsFilters, ProjectStatus } from '@/lib/projects/queries'

export const metadata: Metadata = {
  title: 'Projects — InkOS',
}

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

// Valid board statuses for multi-select
const VALID_STATUSES = new Set<string>([
  'planning',
  'deposit_paid',
  'active',
  'healing',
  'completed',
  'on_hold',
  'cancelled',
])

function getParam(
  params: Record<string, string | string[] | undefined>,
  key: string
): string | undefined {
  const val = params[key]
  return typeof val === 'string' ? val : undefined
}

export default async function ProjectsPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const params = await searchParams

  // Build list filters — multi-status from 'statuses' CSV param
  const filters: ListProjectsFilters = {}

  // Single status (legacy) — kept for backward compat with deep links
  const statusParam = getParam(params, 'status')
  if (statusParam && VALID_STATUSES.has(statusParam)) {
    filters.status = statusParam as ProjectStatus
  }

  // Multi-status via 'statuses' CSV (new)
  const statusesParam = getParam(params, 'statuses')
  if (statusesParam) {
    const statuses = statusesParam
      .split(',')
      .filter((s) => VALID_STATUSES.has(s)) as ProjectStatus[]
    if (statuses.length > 0) {
      // When multi-select, pass only the first as single-filter for now.
      // The client-side filter also filters in-memory on the full set.
      // Full multi-filter support requires an API change — acceptable for Sprint 2.
      filters.status = statuses[0]
    }
  }

  const artistIdParam = getParam(params, 'artistId')
  if (artistIdParam) filters.artistId = artistIdParam

  const clientIdParam = getParam(params, 'clientId')
  if (clientIdParam) filters.clientId = clientIdParam

  const searchParam = getParam(params, 'search')
  if (searchParam) filters.search = searchParam

  const supabase = await createClient()

  const [projects, artistsResult, stats] = await Promise.all([
    listProjects(auth.studioId, filters),
    supabase
      .from('artists')
      .select('id, display_name, avatar_url, sort_order')
      .eq('studio_id', auth.studioId)
      .eq('status', 'active')
      .order('sort_order'),
    getProjectsStats(supabase, auth.studioId),
  ])

  const artists = artistsResult.data ?? []
  const canCreate = auth.role !== 'guest_artist'

  const primaryAction: PageAction | undefined = canCreate
    ? {
        label: 'New project',
        href: '/projects/new',
        icon: <Plus className="h-3.5 w-3.5" aria-hidden="true" />,
      }
    : undefined

  return (
    <Page
      title="Projects"
      subtitle="Multi-session tattoo projects — sleeves, back pieces, bodysuits."
      {...(primaryAction ? { primaryAction } : {})}
    >
      <Suspense
        fallback={
          <div className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-24 rounded-lg" />
              ))}
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
              {Array.from({ length: 8 }).map((_, i) => (
                <Skeleton key={i} className="h-64 rounded-xl" />
              ))}
            </div>
          </div>
        }
      >
        <ProjectsListClient
          initialProjects={projects}
          stats={stats}
          artists={artists}
          role={auth.role}
          initialFilters={filters}
        />
      </Suspense>
    </Page>
  )
}

